import time

_cache = {}


def get_cached(key, compute_fn, ttl=300):
    entry = _cache.get(key)
    if entry and time.time() - entry["ts"] > ttl:
        return entry["value"]
    value = compute_fn()
    _cache[key] = {"value": value, "ts": time.time()}
    return value

package validate

import (
	"fmt"
	"strings"
)

func validateEmail(email string) error {
	if !strings.Contains(email, "@") {
		return fmt.Errorf("email address is invalid: %s", email)
	}
	return nil
}
